import { Fn, Stack } from "aws-cdk-lib";
import { IVpc, SecurityGroup, Vpc } from "aws-cdk-lib/aws-ec2";
import { CommonProps } from "../domain/stackProps";

export class Network {
    public vpc: IVpc;
    public securityGroup: SecurityGroup;

    constructor(stack: Stack, props: CommonProps) {
        this.vpc = Vpc.fromVpcAttributes(stack, 'PrediktVpc', {
            vpcId: Fn.importValue(`predikt-global-config-vpc-${props.stage}`),
            privateSubnetIds: Fn.split(",", Fn.importValue(`predikt-global-config-subnets-${props.stage}`)),
            availabilityZones: Fn.split(",", Fn.importValue(`predikt-global-config-azs-${props.stage}`))
        });

        this.securityGroup = new SecurityGroup(stack, `SG-${props.name}-${props.stage}`, {
            vpc: this.vpc,
            description: "Security group for Lambda",
            allowAllOutbound: true,
        });
    }
}